-- Register official municipal, business, planning and statistical sources for archipelago-wide collection.
on conflict (id) do update set
 name=excluded.name,category=excluded.category,publisher=excluded.publisher,url=excluded.url,
 authority=excluded.authority,scope=excluded.scope,update_note=excluded.update_note,
 last_checked_at=coalesce(excluded.last_checked_at,public.island_sources.last_checked_at),is_active=excluded.is_active;